//! SCAN.POLY.SURF.FAN acceptance tests. Vertex sets and expected fans are in
//! `fixtures/scan/poly/*.fan.txt`, written by the independent Python reference
//! `fixtures/scan/poly/make_fan_fixtures.py` (exact integer predicates, brute-force
//! neighbourhoods); nothing here was generated by running this crate. Fans are compared
//! exactly. The lattice checks (AC-1, AC-2) are hand-labelled from the spec's rules: the
//! analytic triangulation of a triangular lattice, and the square diagonal that avoids the
//! corner with the largest source.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::collections::BTreeMap;

use fid_scan_poly::{fans, Fan, PolyError, PrepVertex, VertexSet, VertexStatus, MAX_GAP, MIN_GAP};

fn read(name: &str) -> String {
    std::fs::read_to_string(format!("{}/fixtures/scan/poly/{name}", fid_testkit::WORKSPACE_ROOT)).unwrap()
}

fn f(s: &str) -> f64 {
    s.parse().unwrap()
}

fn vertex(source: u64, position: [f64; 3], normal: [f64; 3]) -> PrepVertex {
    PrepVertex { source, cell: [0; 3], position, normal, displacement_m: 0.0, status: VertexStatus::Unmoved }
}

fn set(vertices: Vec<PrepVertex>) -> VertexSet {
    VertexSet { vertices, h: 1e-3, smoothing: false, max_displacement_m: 0.0 }
}

struct Case {
    g: f64,
    vs: VertexSet,
    tags: BTreeMap<u64, String>,
    expected: Vec<Fan>,
}

fn ids(s: &str) -> Vec<u64> {
    s.split_whitespace().map(|t| t.parse().unwrap()).collect()
}

fn load(case: &str) -> Case {
    let text = read(&format!("{case}.fan.txt"));
    let mut lines = text.lines().filter(|l| !l.starts_with('#'));
    let mut field = |key: &str| lines.next().unwrap().strip_prefix(&format!("{key} ")).unwrap().to_string();
    assert_eq!(field("case"), case);
    let g = f(&field("g"));
    let n: usize = field("vertices").parse().unwrap();
    let mut vertices = Vec::new();
    let mut tags = BTreeMap::new();
    for _ in 0..n {
        let t: Vec<&str> = lines.next().unwrap().split_whitespace().collect();
        let source: u64 = t[0].parse().unwrap();
        vertices.push(vertex(source, [f(t[1]), f(t[2]), f(t[3])], [f(t[4]), f(t[5]), f(t[6])]));
        tags.insert(source, t[7].to_string());
    }
    assert_eq!(lines.next().unwrap(), format!("fans {n}"));
    let expected: Vec<Fan> = lines
        .map(|l| {
            let parts: Vec<&str> = l.split(';').collect();
            assert_eq!(parts.len(), 3, "{case}: {l}");
            let centre: u64 = parts[0].trim().parse().unwrap();
            let triangles = parts[2]
                .split_whitespace()
                .map(|t| {
                    let (j, k) = t.split_once(':').unwrap();
                    [centre, j.parse().unwrap(), k.parse().unwrap()]
                })
                .collect();
            Fan { centre, neighbours: ids(parts[1]), triangles }
        })
        .collect();
    assert_eq!(expected.len(), n);
    Case { g, vs: set(vertices), tags, expected }
}

const CASES: [&str; 6] =
    ["hex_grid", "hex_grid_wide", "square_grid", "square_grid_tilted", "two_patches_gap", "jitter_dense"];

/// Runs a case with `threads` and compares every fan with the reference.
fn run(case: &str, threads: usize) -> (Case, Vec<Fan>) {
    let c = load(case);
    let got = fans(&c.vs, c.g, threads).unwrap();
    assert_eq!(got.len(), c.expected.len(), "{case}: fan count");
    for (k, (a, b)) in got.iter().zip(&c.expected).enumerate() {
        assert_eq!(a, b, "{case}: fan {k} (centre {})", b.centre);
    }
    (c, got)
}

#[test]
fn every_case_matches_the_reference() {
    for case in CASES {
        run(case, 1);
    }
}

#[test]
fn fans_are_centred_and_edges_shorter_than_g() {
    // REQ-003 and structure: every triangle is centred, ccw-listed vertices are neighbours,
    // and every edge is shorter than g (checked here in plain f64 with a looser margin).
    for case in CASES {
        let (c, got) = run(case, 1);
        let pos: BTreeMap<u64, [f64; 3]> = c.vs.vertices.iter().map(|v| (v.source, v.position)).collect();
        let len = |a: u64, b: u64| {
            let (p, q) = (pos[&a], pos[&b]);
            ((p[0] - q[0]).powi(2) + (p[1] - q[1]).powi(2) + (p[2] - q[2]).powi(2)).sqrt()
        };
        for fan in &got {
            for t in &fan.triangles {
                assert_eq!(t[0], fan.centre);
                assert!(fan.neighbours.contains(&t[1]) && fan.neighbours.contains(&t[2]));
                for (a, b) in [(t[0], t[1]), (t[1], t[2]), (t[2], t[0])] {
                    assert!(len(a, b) < c.g, "{case}: edge {a}-{b} not shorter than g");
                }
            }
        }
    }
}

fn lattice(tag: &str) -> (i32, i32) {
    let (i, j) = tag.split_once(':').unwrap();
    (i.parse().unwrap(), j.parse().unwrap())
}

fn by_lattice(c: &Case) -> BTreeMap<(i32, i32), u64> {
    c.tags.iter().map(|(s, t)| (lattice(t), *s)).collect()
}

/// `got` equals `want` up to a cyclic rotation.
fn is_rotation<T: PartialEq>(got: &[T], want: &[T]) -> bool {
    got.len() == want.len() && (0..want.len()).any(|r| want.iter().cycle().skip(r).take(want.len()).eq(got.iter()))
}

#[test]
fn ac1_hex_grid_interior_fans_are_the_analytic_six() {
    // Lattice offsets in counter-clockwise order about the plane normal U x V.
    const RING: [(i32, i32); 6] = [(1, 0), (0, 1), (-1, 1), (-1, 0), (0, -1), (1, -1)];
    for case in ["hex_grid", "hex_grid_wide"] {
        let (c, got) = run(case, 1);
        let at = by_lattice(&c);
        let mut interior = 0;
        for fan in &got {
            let (i, j) = lattice(&c.tags[&fan.centre]);
            let ring: Option<Vec<u64>> = RING.iter().map(|(di, dj)| at.get(&(i + di, j + dj)).copied()).collect();
            let Some(ring) = ring else { continue };
            interior += 1;
            assert_eq!(fan.triangles.len(), 6, "{case}: ({i},{j})");
            assert!(is_rotation(&fan.neighbours, &ring), "{case}: ({i},{j}) neighbours {:?}", fan.neighbours);
            let want: Vec<[u64; 3]> = (0..6).map(|k| [fan.centre, ring[k], ring[(k + 1) % 6]]).collect();
            assert!(is_rotation(&fan.triangles, &want), "{case}: ({i},{j}) triangles {:?}", fan.triangles);
        }
        assert_eq!(interior, 81, "{case}: interior vertex count");
    }
}

#[test]
fn ac2_square_grid_follows_the_perturbation_and_repeats() {
    let (c, got) = run("square_grid", 1);
    let at = by_lattice(&c);
    // Counter-clockwise about +z: the plane basis is e1 = +y, e2 = -x, so the order of the
    // lattice offsets below (+x, +y, -x, -y) is counter-clockwise about the normal.
    const AXES: [(i32, i32); 4] = [(1, 0), (0, 1), (-1, 0), (0, -1)];
    let mut interior = 0;
    for fan in &got {
        let (i, j) = lattice(&c.tags[&fan.centre]);
        let mut want: Vec<[u64; 3]> = Vec::new();
        let mut complete = true;
        for (q, &a) in AXES.iter().enumerate() {
            let b = AXES[(q + 1) % 4];
            let corner = |d: (i32, i32)| at.get(&(i + d.0, j + d.1)).copied();
            let (Some(pa), Some(pd), Some(pb)) = (corner(a), corner((a.0 + b.0, a.1 + b.1)), corner(b)) else {
                complete = false;
                continue;
            };
            // The diagonal avoids the largest source among the four corners.
            let top = fan.centre.max(pa).max(pd).max(pb);
            if top == fan.centre || top == pd {
                want.push([fan.centre, pa, pb]);
            } else {
                want.push([fan.centre, pa, pd]);
                want.push([fan.centre, pd, pb]);
            }
        }
        if complete {
            interior += 1;
            assert!(is_rotation(&fan.triangles, &want), "({i},{j}): {:?} vs {:?}", fan.triangles, want);
        }
    }
    assert_eq!(interior, 64);
    // Repeated runs and thread counts give identical fans (D0; the CI matrix repeats this on
    // Linux, Windows and macOS against the same reference).
    for threads in [1, 2, 3, 8] {
        assert_eq!(fans(&c.vs, c.g, threads).unwrap(), got);
    }
}

#[test]
fn ac3_no_triangle_spans_the_gap() {
    let (c, got) = run("two_patches_gap", 1);
    let mut triangles = 0;
    for fan in &got {
        for t in &fan.triangles {
            let patch = &c.tags[&t[0]];
            assert!(t.iter().all(|v| &c.tags[v] == patch), "triangle {t:?} spans the gap");
            triangles += 1;
        }
    }
    assert!(triangles > 300);
}

/// A fixed permutation: multiply by a unit modulo n.
fn shuffled(vs: &VertexSet, step: usize) -> VertexSet {
    let n = vs.vertices.len();
    assert_eq!(gcd(step, n), 1);
    let vertices = (0..n).map(|k| vs.vertices[(k * step + 3) % n]).collect();
    VertexSet { vertices, h: vs.h, smoothing: vs.smoothing, max_displacement_m: vs.max_displacement_m }
}

fn gcd(a: usize, b: usize) -> usize {
    if b == 0 {
        a
    } else {
        gcd(b, a % b)
    }
}

#[test]
fn ac4_shuffled_order_and_threads_change_no_fan() {
    for case in CASES {
        let (c, got) = run(case, 1);
        let by_centre: BTreeMap<u64, &Fan> = got.iter().map(|f| (f.centre, f)).collect();
        for (step, threads) in [(7, 1), (13, 4), (31, 9)] {
            let vs = shuffled(&c.vs, step);
            let again = fans(&vs, c.g, threads).unwrap();
            assert_eq!(again.len(), got.len());
            for (v, fan) in vs.vertices.iter().zip(&again) {
                assert_eq!(fan.centre, v.source, "{case}: output follows the vertex-set order");
                assert_eq!(&fan, by_centre.get(&v.source).unwrap(), "{case}: fan of {} changed", v.source);
            }
        }
        for threads in [2, 5, 256] {
            assert_eq!(fans(&c.vs, c.g, threads).unwrap(), got, "{case}: threads {threads}");
        }
    }
}

#[test]
fn neighbourhood_limits() {
    // jitter_dense has the 32-neighbour cap active and normals rotated by 75 degrees or
    // flipped: every fan vertex is within 60 degrees of the centre's normal.
    let (c, got) = run("jitter_dense", 1);
    let normal: BTreeMap<u64, [f64; 3]> = c.vs.vertices.iter().map(|v| (v.source, v.normal)).collect();
    let dot = |a: [f64; 3], b: [f64; 3]| a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
    let mut filtered = 0;
    for fan in &got {
        assert!(fan.neighbours.len() <= 32);
        for v in &fan.neighbours {
            assert!(dot(normal[&fan.centre], normal[v]) >= 0.5, "{} uses {v}", fan.centre);
        }
        if matches!(c.tags[&fan.centre].as_str(), "flipped" | "rotated") {
            filtered += 1;
        }
    }
    assert!(filtered >= 5);
    // Of two vertices at one position only the smaller source is a fan vertex; the larger
    // one's own fan is empty.
    let dups: Vec<u64> = c.tags.iter().filter(|(_, t)| *t == "dup").map(|(s, _)| *s).collect();
    assert_eq!(dups.len(), 2);
    for d in dups {
        let v = c.vs.vertices.iter().find(|v| v.source == d).unwrap();
        let twin = c.vs.vertices.iter().find(|w| w.source != d && w.position == v.position).unwrap();
        let (kept, hidden) = (d.min(twin.source), d.max(twin.source));
        assert!(got.iter().all(|f| !f.neighbours.contains(&hidden)), "{hidden} is a fan vertex");
        assert!(got.iter().find(|f| f.centre == hidden).unwrap().triangles.is_empty());
        assert!(got.iter().any(|f| f.neighbours.contains(&kept)));
    }
}

#[test]
fn invalid_input_is_refused() {
    let c = load("hex_grid");
    let name = |r: Result<Vec<Fan>, PolyError>| match r {
        Err(PolyError::InvalidParameter { name, .. }) => name,
        other => panic!("{other:?}"),
    };
    for g in [0.0, -1e-3, f64::NAN, f64::INFINITY, MIN_GAP / 2.0, MAX_GAP * 2.0] {
        assert_eq!(name(fans(&c.vs, g, 1)), "g", "g = {g}");
    }
    assert!(fans(&c.vs, MIN_GAP, 1).is_ok());
    assert_eq!(name(fans(&c.vs, c.g, 0)), "threads");
    assert_eq!(name(fans(&c.vs, c.g, 257)), "threads");

    let mut vs = c.vs.clone();
    vs.vertices[5].position[1] = f64::NAN;
    assert_eq!(name(fans(&vs, c.g, 1)), "vs.position");
    let mut vs = c.vs.clone();
    vs.vertices[5].position[2] = 1e200;
    assert_eq!(name(fans(&vs, c.g, 1)), "vs.position");
    let mut vs = c.vs.clone();
    vs.vertices[5].normal = [0.0, 0.0, 1.1];
    assert_eq!(name(fans(&vs, c.g, 1)), "vs.normal");
    let mut vs = c.vs.clone();
    vs.vertices[5].normal = [0.0, f64::NAN, 1.0];
    assert_eq!(name(fans(&vs, c.g, 1)), "vs.normal");
    let mut vs = c.vs.clone();
    vs.vertices[9].source = vs.vertices[2].source;
    assert_eq!(name(fans(&vs, c.g, 1)), "vs.source");

    let err = fans(&c.vs, 0.0, 1).unwrap_err();
    assert_eq!(err.code(), "scan.poly.invalid_parameter");
    assert_eq!(fans(&set(Vec::new()), 1e-3, 4).unwrap(), Vec::<Fan>::new());
}

#[test]
fn lone_and_paired_vertices_have_empty_fans() {
    let n = [0.0, 0.0, 1.0];
    let one = set(vec![vertex(4, [0.0; 3], n)]);
    assert_eq!(fans(&one, 1e-3, 1).unwrap(), vec![Fan { centre: 4, neighbours: vec![], triangles: vec![] }]);
    let two = set(vec![vertex(4, [0.0; 3], n), vertex(2, [5e-4, 0.0, 0.0], n)]);
    let got = fans(&two, 1e-3, 2).unwrap();
    assert!(got.iter().all(|f| f.triangles.is_empty() && f.neighbours.is_empty()));
    // Three vertices of an equilateral triangle with side s: one triangle each when g > s,
    // none when g = s (an edge of length g is not shorter than g).
    let s = 1e-3;
    let tri = set(vec![
        vertex(10, [0.0, 0.0, 0.0], n),
        vertex(11, [s, 0.0, 0.0], n),
        vertex(12, [s * 0.5, s * (3f64.sqrt() / 2.0), 0.0], n),
    ]);
    let got = fans(&tri, s * 1.001, 1).unwrap();
    assert_eq!(got[0].triangles, vec![[10, 11, 12]]);
    assert_eq!(got[1].triangles, vec![[11, 12, 10]]);
    assert_eq!(got[2].triangles, vec![[12, 10, 11]]);
    let exact = set(vec![vertex(10, [0.0; 3], n), vertex(11, [s, 0.0, 0.0], n), vertex(12, [0.0, s, 0.0], n)]);
    assert!(fans(&exact, s, 1).unwrap().iter().all(|f| f.triangles.is_empty()));
}
